'use strict';
const fs=require('node:fs');const path=require('node:path');const zlib=require('node:zlib');const crypto=require('node:crypto');const React=require('react');const {renderToStaticMarkup}=require('react-dom/server');const {buildCore}=require('./performance-core-build.cjs');
const dimensions=[{width:1280,height:900},{width:390,height:844},{width:320,height:720}],counts=[12,120,600];
function grid(implementations,count){return React.createElement('main',{'data-performance-fixture':'same-source-same-identity-count'},Array.from({length:count},(_,index)=>{const row=implementations[index%implementations.length];return React.createElement('figure',{key:'identity-'+index,'data-identity':'identity-'+index,style:{width:200,height:150,margin:8}},React.createElement(row.Picture,{src:'/synthetic-image.svg?asset='+Math.floor(index/4),alt:'合成身份 '+index+' / '+row.name,priority:index===0,complete:true,fit:'contain'}));}));}
async function measure({phase,outputDirectory}){fs.mkdirSync(outputDirectory,{recursive:true});const file=path.join(outputDirectory,phase+'-image-core.cjs');const proof=await buildCore({phase,output:file});const code=fs.readFileSync(file);const module=require(file);const rows=[];
 for(const viewport of dimensions)for(const count of counts){const html=renderToStaticMarkup(grid(module.implementations,count));const tags=html.match(/<[a-z][a-z0-9-]*(?=[\s>])/g)||[];const imgs=[...html.matchAll(/<img\b[^>]*>/g)].map(m=>m[0]);rows.push({viewport,count,measurement:'deterministic React SSR markup, not browser layout/experience',domElementCount:tags.length,imgCount:imgs.length,nonemptySrcCount:imgs.filter(tag=>/\bsrc="[^\"]+"/.test(tag)).length,uniqueSrcCount:new Set(imgs.map(tag=>(tag.match(/\bsrc="([^\"]+)"/)||[])[1])).size,altCount:imgs.filter(tag=>/\balt="[^\"]+"/.test(tag)).length,eagerCount:imgs.filter(tag=>/\bloading="eager"/.test(tag)).length,highPriorityCount:imgs.filter(tag=>/\bfetchPriority="high"/.test(tag)).length,lazyCount:imgs.filter(tag=>/\bloading="lazy"/.test(tag)).length,asyncDecodeCount:imgs.filter(tag=>/\bdecoding="async"/.test(tag)).length,htmlBytes:Buffer.byteLength(html),htmlSha256:crypto.createHash('sha256').update(html).digest('hex')});}
 const report={phase,measuredAt:new Date().toISOString(),baselineCapture:require('./performance-before-impls.json').capturedAt,method:'Identical fixture, count, dimensions, source patterns, alt text and first-image priority. Actual image functions extracted verbatim by TypeScript AST. Core JS excludes external React/ReactDOM/lucide, common to both. SSR counts are deterministic markup only.',coreJs:{rawBytes:code.length,gzipBytes:zlib.gzipSync(code,{level:9}).length,sha256:crypto.createHash('sha256').update(code).digest('hex'),external:['react','react-dom','lucide-react']},ssr:rows,proof,browser:{state:'not-run',reason:'Existing Playwright browser binary is absent; no installation or alternate/bypass attempted.',LCP:null,CLS:null,requestCount:null,duplicateRequests:null,firstVisibleMs:null,scrollLoad:null,runCount:0,median:null,p95:null}};fs.writeFileSync(path.join(outputDirectory,phase+'-deterministic.json'),JSON.stringify(report,null,2)+'\n');return report;}
if(require.main===module){const phase=process.argv[2],outputDirectory=process.argv[3];if(!outputDirectory||!path.isAbsolute(outputDirectory))throw new Error('Use phase plus absolute output directory outside source.');measure({phase,outputDirectory}).then(report=>console.log(JSON.stringify({phase,coreJs:report.coreJs,ssrRows:report.ssr.length,first:report.ssr[0]}))).catch(error=>{console.error(error);process.exitCode=1;});}
module.exports={measure,grid,dimensions,counts};
